    [Fact]
    public async Task Generator_WithSpecColumnResolver_EmitsColumnResolverImplementation()
    {
        var testCode = """
            using EricksonLopez.Specification;

            namespace MyDomain;

            public class Customer
            {
                public int Id { get; set; }
                public string Name { get; set; } = "";
                public decimal TotalPurchases { get; set; }
            }

            [SpecColumnResolver(typeof(Customer))]
            public partial class CustomerColumns
            {
            }
            """;

        var expectedCode = """
            // <auto-generated/>
            #nullable enable
            namespace MyDomain;

            partial class CustomerColumns : global::EricksonLopez.Specification.Sql.IColumnNameResolver
            {
                public static readonly CustomerColumns Instance = new();

                public string Resolve(string propertyName) => propertyName switch
                {
                    "Id" => "id",
                    "Name" => "name",
                    "TotalPurchases" => "total_purchases",
                    _ => throw new global::System.ArgumentException($"Unknown property '{propertyName}' for entity 'Customer'.", nameof(propertyName))
                };
            }
            """;

        var test = new CSharpSourceGeneratorTest<SpecificationGenerator, DefaultVerifier>
        {
            TestCode = testCode,
            CompilerDiagnostics = CompilerDiagnostics.None,
        };

        test.TestState.AdditionalReferences.Add(typeof(EricksonLopez.Specification.Sql.IColumnNameResolver).Assembly);

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecAttribute.g.cs",
            ExpectedAttributeSource));
        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecColumnResolverAttribute.g.cs",
            ExpectedColumnResolverAttributeSource));

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "CustomerColumns.g.cs",
            expectedCode));

        await test.RunAsync();
    }

