    [Fact]
    public void ConvertName_And_ToSnakeCase_WithEdgeCases_TransformsCorrectly()
    {
        var convertMethod = typeof(SpecificationGenerator).GetMethod("ConvertName", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)!;
        var toSnakeCaseMethod = typeof(SpecificationGenerator).GetMethod("ToSnakeCase", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)!;

        // ConvertName conventions:
        convertMethod.Invoke(null, new object[] { "FirstName", 1 }).Should().Be("FirstName"); // Pascal
        convertMethod.Invoke(null, new object[] { "FirstName", 2 }).Should().Be("firstName"); // Camel
        convertMethod.Invoke(null, new object[] { "FirstName", 3 }).Should().Be("FirstName"); // Exact
        convertMethod.Invoke(null, new object[] { "FirstName", 0 }).Should().Be("first_name"); // Snake

        // ToSnakeCase empty and edge cases
        toSnakeCaseMethod.Invoke(null, new object[] { "" }).Should().Be("");
        toSnakeCaseMethod.Invoke(null, new object[] { "A" }).Should().Be("a");
        toSnakeCaseMethod.Invoke(null, new object[] { "already_snake" }).Should().Be("already_snake");
        toSnakeCaseMethod.Invoke(null, new object[] { "already_Snake" }).Should().Be("already_snake");
    }

