    public async Task Generator_WithSpec_IgnoresPrivateAndStaticProperties()
    {
        var testCode = """
            using EricksonLopez.Specification;

            namespace MyDomain;

            public class Customer
            {
                public int Id { get; set; }
                public static string Category { get; set; } = "VIP";
                private string Secret { get; set; } = "hidden";
            }

            [Spec(typeof(Customer))]
            public partial class CustomerSpec
            {
            }
            """;

        var expectedCode = """
            // <auto-generated/>
            namespace MyDomain;

            partial class CustomerSpec
            {
                public static readonly global::System.Linq.Expressions.Expression<global::System.Func<global::MyDomain.Customer, object?>> OrderById = x => (object?)x.Id;
            }
            """;

        var test = new CSharpSourceGeneratorTest<SpecificationGenerator, DefaultVerifier>
        {
            TestCode = testCode,
            CompilerDiagnostics = CompilerDiagnostics.None,
        };

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecAttribute.g.cs",
            ExpectedAttributeSource));
        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecColumnResolverAttribute.g.cs",
            ExpectedColumnResolverAttributeSource));

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "CustomerSpec.g.cs",
            expectedCode));

        await test.RunAsync();
    }

    [Fact]
    public async Task Generator_WithSpec_WithNonSpecificationGenericBase_EmitsDefaultComment()
    {
        var testCode = """
            using EricksonLopez.Specification;

            namespace MyDomain;

            public class Customer
            {
                public int Id { get; set; }
            }

            public abstract class OtherBase<T> { }

            [Spec]
            public partial class CustomerSpec : OtherBase<Customer>
            {
            }
            """;

        var expectedCode = """
            // <auto-generated/>
            namespace MyDomain;

            partial class CustomerSpec
            {
                // Strongly-typed ordering helpers generated by EricksonLopez.Specification.Generators
                // Add properties to your entity class and they will appear here as ordering expressions.
            }
            """;

        var test = new CSharpSourceGeneratorTest<SpecificationGenerator, DefaultVerifier>
        {
            TestCode = testCode,
            CompilerDiagnostics = CompilerDiagnostics.None,
        };

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecAttribute.g.cs",
            ExpectedAttributeSource));
        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "SpecColumnResolverAttribute.g.cs",
            ExpectedColumnResolverAttributeSource));

        test.TestState.GeneratedSources.Add((
            typeof(SpecificationGenerator),
            "CustomerSpec.g.cs",
            expectedCode));

        await test.RunAsync();
    }
